{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_D2C_App_Target_vs_Achieved AS WITH Target AS ( SELECT Safe.parse_date(\'%Y-%m-%d\',Start_Date) AS Target_Date, Channel, safe_cast(REPLACE(Target,\",\",\'\' )AS float64) AS Target FROM `MapleMonk.Zouk_d2c_App_Target` ), Metrics AS ( SELECT safe.parse_date(\'%Y-%m-%d\',Date) AS Date, Channel, Sum(CASE WHEN lower(Metrics) = \'sessions\' Then cast(replace(Value,\',\',\'\') as float64) ELSE 0 END) AS Session, Sum(CASE WHEN lower(Metrics) = \'install_total\' Then cast(replace(Value,\',\',\'\') as float64) ELSE 0 END) AS Total_Install, Sum(CASE WHEN lower(Metrics) = \'installs_meta\' Then cast(replace(Value,\',\',\'\') as float64) ELSE 0 END) AS Meta_Installs, Sum(CASE WHEN lower(Metrics) = \'uninstalls\' Then cast(replace(Value,\',\',\'\') as float64) ELSE 0 END) AS Uninstalls, Sum(CASE WHEN lower(Metrics) = \'amount spent\' Then cast(replace(Value,\',\',\'\') as float64) ELSE 0 END) AS Amount_Spent, Sum(CASE WHEN lower(Metrics) = \'meta ad cpi\' Then cast(replace(Value,\',\',\'\') as float64) ELSE 0 END) AS Meta_Ad_CPI FROM `MapleMonk.Zouk_d2c_App_Metrics` GROUP By 1,2 ), Sales AS ( SELECT Date, MARKETPLACE, CASE WHEN Lower(MARKETPLACE) like any (\'shopify android app\', \'shopify app\') THEN \'Android\' WHEN Lower(MARKETPLACE) like \'shopify ios app\' THEN \'iOS\' ELSE \'App\' END AS Channel, new_customer_flag, customer_id_final, REFERENCE_CODE, Payment_Mode, sum(Quantity) AS Quantity, sum(Net_Revenue) AS Net_Revenue FROM `MapleMonk.Zouk_DTC_Net_Sales` WHERE Lower(MARKETPLACE) like \'%app%\' and Date < Current_Date(\'Asia/Kolkata\') GROUP BY 1,2,3,4,5,6,7 ), Combined AS ( SELECT COALESCE(t.Target_Date,s.Date) AS Date, Marketplace, COALESCE(s.Channel,t.Channel) AS Channel, new_customer_flag, customer_id_final, Reference_code, Payment_Mode, Quantity, Net_Revenue, Ifnull(t.Target,0) AS Target, ifnull(m.Session,0) AS Session, ifnull(m.total_install,0) AS Total_Install, ifnull(m.meta_installs,0) AS Meta_Install, ifnull(m.uninstalls,0) AS Uninstall, ifnull(m.amount_Spent,0) AS Amount_Spent, ifnull(m.meta_ad_cpi,0) AS Meta_Ad_CPI, ROW_NUMBER() OVER (PARTITION BY coalesce(t.target_date,s.Date), coalesce(t.channel,s.Channel) ORDER BY s.Reference_Code) AS rn FROM Target t FULL OUTER JOIN Sales s ON t.Target_Date = s.Date AND lower(t.Channel) = lower(s.Channel) FULL OUTER JOIN Metrics m ON COALESCE(t.Target_Date,s.Date) = m.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(m.Channel) ) SELECT Date, MARKETPLACE, Channel, new_customer_flag, customer_id_final, Reference_code, Payment_Mode, Quantity, Net_Revenue, IF(rn = 1, IFNULL(Target,0), 0) AS Target, IF(rn = 1, IFNULL(Session, 0), 0) AS Session, IF(rn = 1, IFNULL(Total_Install, 0), 0) AS Total_Install, IF(rn = 1, IFNULL(Meta_Install, 0), 0) AS Meta_Install, IF(rn = 1, IFNULL(Uninstall, 0), 0) AS Uninstall, IF(rn = 1, IFNULL(Amount_Spent, 0), 0) AS Amount_Spent, IF(rn = 1, IFNULL(Meta_Ad_CPI, 0), 0) AS Meta_Ad_CPI FROM Combined ORDER BY Date, Channel, rn ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            